export const formFieldSeeds: readonly FormFieldSeed[] = [
  ...COLOMBIA_FORM_FIELDS,
  ...CHILE_FORM_FIELDS,
];

/**
 * Idempotent bootstrap seeding for US-01.
 *
 * Rules (see `.opencode/skills/strapi-multi-country/SKILL.md` §3 and
 * `specs/US-01-policyholder-vehicle-form.md` §3):
 * - natural key for `country-config` is `country`;
 * - natural key for `form-field` is `(country, key)`;
 * - an entry is only created when no draft AND no published version exists,
 *   so restarting the stack never duplicates or mutates business-edited rows;
 * - new entries are published immediately (`status: 'published'`).
 */
import type { Core } from '@strapi/strapi';

import {
  countryConfigSeeds,
  type CountryConfigSeed,
  formFieldSeeds,
  type FormFieldSeed,
} from './seed-data';

type SeedStatus = 'draft' | 'published';

interface SeedDocumentService<TData extends object> {
  findMany(params: {
    filters: Record<string, unknown>;
    status: SeedStatus;
  }): Promise<ReadonlyArray<unknown>>;
  create(params: { data: TData; status: SeedStatus }): Promise<unknown>;
}

/**
 * Narrow, typed view over the Strapi 5 Document Service.
 *
 * The cast keeps the bootstrap independent from generated content-type typings
 * (`types/generated/contentTypes.d.ts`); payloads are still validated by the
 * Document Service itself at runtime.
 */
const documentService = <TData extends object>(
  strapi: Core.Strapi,
  uid: string
): SeedDocumentService<TData> =>
  strapi.documents(uid as never) as unknown as SeedDocumentService<TData>;

const existsWithStatus = async (
  documents: SeedDocumentService<object>,
  filters: Record<string, unknown>,
  status: SeedStatus
): Promise<boolean> => {
  const entries = await documents.findMany({ filters, status });
  return entries.length > 0;
};

/**
 * `findMany` defaults to the draft version in Strapi 5, so both statuses are
 * queried explicitly: a published document still has a draft counterpart, but
 * checking both guarantees an unpublished hand-made entry is never duplicated.
 */
const entryExists = async (
  documents: SeedDocumentService<object>,
  filters: Record<string, unknown>
): Promise<boolean> => {
  if (await existsWithStatus(documents, filters, 'draft')) {
    return true;
  }

  return existsWithStatus(documents, filters, 'published');
};

const seedCountryConfigs = async (strapi: Core.Strapi): Promise<void> => {
  const documents = documentService<CountryConfigSeed>(
    strapi,
    'api::country-config.country-config'
  );

  for (const config of countryConfigSeeds) {
    const exists = await entryExists(documents, { country: config.country });

    if (exists) {
      continue;
    }

    await documents.create({ data: config, status: 'published' });
    strapi.log.info(`[bootstrap] Seeded country-config for ${config.country}.`);
  }
};

const seedFormFields = async (strapi: Core.Strapi): Promise<void> => {
  const documents = documentService<FormFieldSeed>(strapi, 'api::form-field.form-field');

  for (const field of formFieldSeeds) {
    const exists = await entryExists(documents, {
      country: field.country,
      key: field.key,
    });

    if (exists) {
      continue;
    }

    await documents.create({ data: field, status: 'published' });
    strapi.log.info(`[bootstrap] Seeded form-field ${field.country}/${field.key}.`);
  }
};

export const seedContent = async (strapi: Core.Strapi): Promise<void> => {
  await seedCountryConfigs(strapi);
  await seedFormFields(strapi);

  strapi.log.info(
    `[bootstrap] Seed verified: ${countryConfigSeeds.length} country configs and ${formFieldSeeds.length} form fields for CO/CL.`
  );
};

/**
 * Programmatic Public-role hardening (ADR-002, US-01 §4.5).
 *
 * The Angular application is fully anonymous and read-only: it never sends an
 * `Authorization` header and no API token exists. The only browser access path
 * is therefore the users-permissions `Public` role, which must keep exactly the
 * read-only actions listed below and nothing else.
 *
 * The configuration is a full replacement, not an addition: any other
 * permission attached to `Public` (including `api::*`, `plugin::users-permissions.*`
 * and `plugin::upload.*` entries) is revoked, so the default is denial.
 */
import type { Core } from '@strapi/strapi';

export const PUBLIC_READ_ACTIONS = [
  'api::form-field.form-field.find',
  'api::form-field.form-field.findOne',
  'api::country-config.country-config.find',
  'api::country-config.country-config.findOne',
] as const;

interface RoleRecord {
  readonly id: number;
  readonly type: string | null;
}

interface PermissionRecord {
  readonly id: number;
  readonly action: string;
}

const PUBLIC_ROLE_TYPE = 'public';

export const configurePublicRolePermissions = async (strapi: Core.Strapi): Promise<void> => {
  const publicRole = (await strapi.db.query('plugin::users-permissions.role').findOne({
    where: { type: PUBLIC_ROLE_TYPE },
  })) as RoleRecord | null;

  if (!publicRole) {
    // Fail closed: without the Public role the read-only posture cannot be verified.
    throw new Error(
      '[bootstrap] users-permissions Public role was not found; refusing to start with an unverified permission set.'
    );
  }

  const permissionStore = strapi.db.query('plugin::users-permissions.permission');

  const currentPermissions = (await permissionStore.findMany({
    where: { role: { id: publicRole.id } },
  })) as PermissionRecord[];

  const allowlist = new Set<string>(PUBLIC_READ_ACTIONS);
  const keptActions = new Set<string>();
  const permissionsToRevoke: PermissionRecord[] = [];

  for (const permission of currentPermissions) {
    // Keep the first record per allowed action; revoke everything else,
    // including duplicates of an allowed action.
    if (!allowlist.has(permission.action) || keptActions.has(permission.action)) {
      permissionsToRevoke.push(permission);
      continue;
    }

    keptActions.add(permission.action);
  }

  for (const permission of permissionsToRevoke) {
    await permissionStore.delete({ where: { id: permission.id } });
  }

  const permissionsToGrant = PUBLIC_READ_ACTIONS.filter((action) => !keptActions.has(action));

  for (const action of permissionsToGrant) {
    await permissionStore.create({ data: { action, role: publicRole.id } });
  }

  strapi.log.info(
    `[bootstrap] Public role locked to ${PUBLIC_READ_ACTIONS.length} read-only actions ` +
      `(revoked: ${permissionsToRevoke.length}, granted: ${permissionsToGrant.length}).`
  );
};

